CREATE TABLE p_lew_core.t_customer_complaint_case_hist (
   client_id                           NUMBER(38,0)    NOT NULL COMMENT 'DWH-Mandant; FK auf CLIENT',
   cust_complaint_sid                  NUMBER(38,0)    NOT NULL COMMENT 'Surrogate Key for customer compaint case',
   src_client_id                       VARCHAR(250)    COMMENT 'Client id derived from the data in source system , might be nul',
   item_sid                            NUMBER(38,0)    COMMENT 'Surrogate Key ITEM (eindeutig ueber alle Laender/Mandanten hinweg)',
   src_item_nr                         VARCHAR(250)    COMMENT 'Technical Identifier from source system',
   src_item_name                       VARCHAR(250)    COMMENT 'Product  Name from source system',
   src_item_descr                      VARCHAR(250)    COMMENT 'Product  Description from source system',
   src_item_long_descr                 VARCHAR(250)    COMMENT 'Product: Long formatted description from source system',
   src_item_ian                        VARCHAR(250)    COMMENT 'Product:  from source system',
   src_item_gtin                       VARCHAR(250)    COMMENT 'Product EAN GTIN from source system',
   src_item_gtin_descr                 VARCHAR(250)    COMMENT 'Product: Description EAN from source system',
   src_item_sap_nr                     VARCHAR(250)    COMMENT 'Stores the online shop SAP article number from source system',
   item_grp_sid                        NUMBER(38,0)    COMMENT 'Surrogate Key ITEM GROUP',
   src_item_group_nr                   VARCHAR(250)    COMMENT 'Merchandise subgroup name  as coming from Salesforce',
   src_item_group_name                 VARCHAR(100)    COMMENT 'Merchandise subgroup picklist  as coming from Salesforce',
   item_fam_grp_sid                    NUMBER(38,0)    COMMENT 'Surrogate Key ITEM FAMILYGROUP;',
   src_item_family_nr                  VARCHAR(250)    COMMENT 'Merchandise family number as coming from Salesforce',
   src_item_family_name                VARCHAR(100)    COMMENT 'Merchandise family number  name  as coming from Salesforce',
   cust_complaint_srv_center_cd        VARCHAR(20)     COMMENT 'The code for the service center for proceeding customer complaint cases.',
   cust_complaint_srv_area_cd          VARCHAR(20)     COMMENT 'The code for the service area originating customer complaint cases',
   orig_cust_complaint_srv_area_cd     VARCHAR(20)     COMMENT 'The code for the service area originating customer complaint cases',
   cust_complaint_contact_type_cd      VARCHAR(20)     COMMENT 'A code for customer complaint type',
   cust_complaint_status_cd            VARCHAR(250)    COMMENT 'Status code that uniqly identify customer case status ( assigned by DWH)',
   cust_complaint_sales_channel_cd     VARCHAR(20)     COMMENT 'A code for customer complaint sales channel',
   cust_complaint_origin_cd            VARCHAR(20)     COMMENT 'A code for customer complaint  origin (Webform, etc)',
   cust_complaint_origin_group_name    VARCHAR(100)    COMMENT 'A code for customer complaint  origin (Webform, etc)',
   brand_sid                           NUMBER(38,0)    COMMENT 'Surrogate Key BRAND;',
   src_brand_name                      VARCHAR(100)    COMMENT 'Product Brand Name from source system',
   sup_sid                             NUMBER(38,0)    COMMENT 'Surrogate Key SUPPLIER',
   src_sup_nr                          VARCHAR(100)    COMMENT 'Source Supplier Number',
   src_sup_name                        VARCHAR(100)    COMMENT 'Source Supplier Name',
   store_loc_sid                       NUMBER(38,0)    COMMENT 'Surrogate Key LOCATION (eindeutig ueber alle Laender/Mandanten hinweg)',
   src_store_name                      VARCHAR(100)    COMMENT 'Related store-account name',
   wh_loc_sid                          NUMBER(38,0)    COMMENT 'Surrogate Key LOCATION (eindeutig ueber alle Laender/Mandanten hinweg)',
   src_wh_name                         VARCHAR(100)    COMMENT 'Related warehouse name',
   src_wh_acct_name                    VARCHAR(100)    COMMENT 'Related warehouse name',
   src_wh_descr                        VARCHAR(100)    COMMENT 'Related warehouse description',
   cust_complaint_cat_sid              NUMBER(38,0)    COMMENT 'Surrogate Key for category',
   cust_complaint_cat_nr               VARCHAR(250)    COMMENT 'Category Number',
   cust_complaint_low_lvl_cat_name     VARCHAR(100)    COMMENT 'Customer Category Lowest Level Name',
   cust_complaint_reason               VARCHAR(250)    COMMENT 'Reason for Complaints QA',
   cust_complaint_short_descr          VARCHAR(400)    COMMENT 'Short Description',
   cust_complaint_descr                VARCHAR(50000)  COMMENT 'Full Description of the Case',
   lot_nr                              VARCHAR(100)    COMMENT 'Lot / Batch Number',
   purchase_dt                         DATE            COMMENT 'Date of Purchase',
   best_before_dt                      DATE            COMMENT 'Best before date',
   case_close_dt                       DATE            COMMENT 'Date of closing the case',
   is_critical_fg                      NUMBER(38,0)    COMMENT 'Is case critical',
   is_illness_injury_fg                NUMBER(38,0)    COMMENT 'Did Illness / Injury Occur?',
   is_main_case_fg                     NUMBER(38,0)    COMMENT 'Indicates if a case is a main case vs sub case ',
   is_sub_case_fg                      NUMBER(38,0)    COMMENT 'Indicates if a case is a sub case vs main case ',
   is_parent_case_fg                   NUMBER(38,0)    COMMENT 'Indicates if a case is a parent case vs child case ',
   is_child_case_fg                    NUMBER(38,0)    COMMENT 'Indicates if a case is a child case vs parent case ',
   is_merge_case_fg                    NUMBER(38,0)    COMMENT 'Indicates if a case is a merged case',
   dwh_valid_from                      DATE            NOT NULL COMMENT 'Gueltigkeitsbeginn; Teil der DWH-Historisierung; aeltester Satz der Historie erhaelt immer den Wert 01.01.1900 ("minus unendlich")',
   deleted_fg                          NUMBER(38,0)    NOT NULL COMMENT 'Artikel ist im Falle deleted_fg = 1 im Zeitraum dwh_valid_from / dwh_valid_to nicht im Quellsystem bekannt; Hinweis: auch bei gesetztem Loeschkz im Quellsystem wird dieser Status angenommen',
   dwh_valid_to                        DATE            NOT NULL COMMENT 'Gueltigkeitsende; Teil der DWH-Historisierung; neuster Satz der Historie erhaelt immer den Wert 30.12.9999 ("plus unendlich")',
   dwh_load_id                         NUMBER(38,0)    NOT NULL,
   dwh_created                         TIMESTAMP_NTZ(9) NOT NULL,
   dwh_updated                         TIMESTAMP_NTZ(9) NOT NULL,
   CONSTRAINT PK_T_CUSTOMER_COMPLAINT_CASE_H PRIMARY KEY (cust_complaint_sid, dwh_valid_from)
       NOT ENFORCED
)COMMENT = 'The table contais customer complait cases opened in Salesforce or BSI system as a result of a customer reporting issues via mail , web-form or phone ( historized version)';
